import { useForm, useFieldArray } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import Modal from "./Modal";
import Input from "./ui/Input";
import SegmentedControl from "./ui/SegmentedControl";
import { useEffect, useState } from "react";
import { Plus, Trash2, MapPin, Paperclip, Users, Building2, User } from "lucide-react";
import { cn } from "@/lib/utils";

const contactSchema = z.object({
    name: z.string().min(1, "Nome obrigatório"),
    department: z.string().min(1, "Departamento obrigatório"),
    email: z.string().email("E-mail inválido").optional().or(z.literal("")),
    phone: z.string().optional().or(z.literal("")),
});

const customerSchema = z.object({
    name: z.string().min(3, "Nome deve ter pelo menos 3 caracteres"),
    doc: z.string().optional().or(z.literal("")),
    email: z.string().email("E-mail inválido").optional().or(z.literal("")),
    phone: z.string().optional().or(z.literal("")),
    status: z.enum(["Lead", "Oportunidade", "Ativo", "Vencido", "Arquivado"]),
    origin: z.enum(["Próprio", "Concorrente"]),
    certificate_type: z.string().optional().or(z.literal("")),
    expiry_date: z.string().optional().or(z.literal("")),

    // Novos campos
    address_zip: z.string().optional(),
    address_street: z.string().optional(),
    address_number: z.string().optional(),
    address_complement: z.string().optional(),
    address_neighborhood: z.string().optional(),
    address_city: z.string().optional(),
    address_state: z.string().optional(),

    document_url: z.string().optional(),
    responsible_cpf: z.string().optional(),
    parent_id: z.string().optional(),

    contacts: z.array(contactSchema).optional(),
});

type CustomerFormData = z.infer<typeof customerSchema>;

interface CustomerModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (data: CustomerFormData) => void;
    initialData?: any;
    title: string;
}

export default function CustomerModal({ isOpen, onClose, onSubmit, initialData, title }: CustomerModalProps) {
    const [activeSection, setActiveSection] = useState<"dados" | "endereco" | "documentos" | "contatos">("dados");

    const {
        register,
        handleSubmit,
        reset,
        setValue,
        watch,
        control,
        formState: { errors, isSubmitting }
    } = useForm<CustomerFormData>({
        resolver: zodResolver(customerSchema),
        defaultValues: {
            status: "Lead",
            origin: "Próprio",
            contacts: []
        }
    });

    const { fields, append, remove } = useFieldArray({
        control,
        name: "contacts"
    });

    const statusValue = watch("status");
    const originValue = watch("origin");
    const docValue = watch("doc");

    useEffect(() => {
        if (initialData) {
            reset({
                ...initialData,
                expiry_date: initialData.expiry_date ? new Date(initialData.expiry_date).toISOString().split('T')[0] : "",
                contacts: initialData.contacts || []
            });
        } else {
            reset({
                name: "",
                doc: "",
                email: "",
                phone: "",
                status: "Lead",
                origin: "Próprio",
                certificate_type: "",
                expiry_date: "",
                address_zip: "",
                address_street: "",
                address_number: "",
                address_complement: "",
                address_neighborhood: "",
                address_city: "",
                address_state: "",
                document_url: "",
                responsible_cpf: "",
                parent_id: "",
                contacts: []
            });
        }
    }, [initialData, reset, isOpen]);

    const isPJ = docValue?.replace(/\D/g, '').length === 14;

    const sections = [
        { id: "dados", label: "Dados Básicos", icon: Users },
        { id: "endereco", label: "Endereço", icon: MapPin },
        { id: "documentos", label: "Documentos", icon: Paperclip },
        { id: "contatos", label: "Contatos", icon: Building2 },
    ];

    return (
        <Modal isOpen={isOpen} onClose={onClose} title={title}>
            {/* Tabs Navigation - Denser */}
            <div className="flex p-0.5 bg-slate-100 dark:bg-slate-900 rounded-none mb-4 overflow-x-auto no-scrollbar">
                {sections.map((section) => (
                    <button
                        key={section.id}
                        type="button"
                        onClick={() => setActiveSection(section.id as any)}
                        className={cn(
                            "flex items-center gap-2 px-3 py-2 rounded-none text-[10px] font-bold transition-all whitespace-nowrap flex-1 justify-center",
                            activeSection === section.id
                                ? "bg-white dark:bg-slate-800 text-primary shadow-sm"
                                : "text-slate-500 hover:text-slate-700 dark:hover:text-slate-300"
                        )}
                    >
                        <section.icon size={14} />
                        {section.label}
                    </button>
                ))}
            </div>

            <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
                {activeSection === "dados" && (
                    <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-300">
                        {/* Status/Origin Group - Denser */}
                        <div className="p-4 bg-slate-50 dark:bg-slate-900/50 rounded-none border border-slate-200 dark:border-slate-800 transition-all">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Origem do Cliente</label>
                                    <SegmentedControl
                                        options={["Próprio", "Concorrente"]}
                                        value={originValue}
                                        onChange={(v) => setValue("origin", v as any)}
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Status CRM</label>
                                    <SegmentedControl
                                        options={["Lead", "Oportunidade", "Ativo", "Vencido", "Arquivado"]}
                                        value={statusValue}
                                        onChange={(v) => setValue("status", v as any)}
                                    />
                                </div>
                            </div>
                        </div>

                        <Input
                            label="Nome Completo / Razão Social"
                            {...register("name")}
                            error={errors.name?.message}
                            placeholder="Ex: João Silva ou Empresa LTDA"
                            helpText="Identificação clara agiliza o processo de emissão."
                        />

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <Input
                                label="CPF / CNPJ"
                                {...register("doc")}
                                error={errors.doc?.message}
                                placeholder="000.000.000-00"
                            />
                            <Input
                                label="Telefone WhatsApp"
                                {...register("phone")}
                                error={errors.phone?.message}
                                placeholder="(11) 99999-9999"
                            />
                        </div>

                        <Input
                            label="E-mail de Faturamento"
                            {...register("email")}
                            error={errors.email?.message}
                            placeholder="exemplo@email.com"
                        />

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 p-4 bg-slate-50 dark:bg-slate-900/50 rounded-2xl border border-slate-200 dark:border-slate-800">
                            <Input
                                label="Tipo de Certificado"
                                {...register("certificate_type")}
                                placeholder="Ex: e-CPF A1"
                            />
                            <Input
                                label="Data de Vencimento"
                                type="date"
                                {...register("expiry_date")}
                            />
                        </div>
                    </div>
                )}

                {activeSection === "endereco" && (
                    <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-300">
                        <div className="grid grid-cols-3 gap-4">
                            <div className="col-span-1">
                                <Input label="CEP" {...register("address_zip")} placeholder="00000-000" />
                            </div>
                            <div className="col-span-2">
                                <Input label="Logradouro" {...register("address_street")} placeholder="Rua, Av..." />
                            </div>
                        </div>

                        <div className="grid grid-cols-3 gap-4">
                            <Input label="Número" {...register("address_number")} placeholder="123" />
                            <div className="col-span-2">
                                <Input label="Complemento" {...register("address_complement")} placeholder="Apto, Sala..." />
                            </div>
                        </div>

                        <Input label="Bairro" {...register("address_neighborhood")} placeholder="Centro" />

                        <div className="grid grid-cols-2 gap-4">
                            <Input label="Cidade" {...register("address_city")} placeholder="São Paulo" />
                            <Input label="Estado" {...register("address_state")} placeholder="SP" />
                        </div>
                    </div>
                )}

                {activeSection === "documentos" && (
                    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
                        <div className="p-8 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-[2.5rem] flex flex-col items-center justify-center text-center">
                            <div className="size-16 rounded-3xl bg-primary/10 text-primary flex items-center justify-center mb-4">
                                <Paperclip size={24} />
                            </div>
                            <h3 className="text-sm font-black uppercase tracking-widest mb-1">Cópia da CNH ou RG</h3>
                            <p className="text-[10px] text-slate-500 font-bold max-w-[200px] mb-6">Documento obrigatório para emissão do certificado.</p>
                            <button
                                type="button"
                                className="px-6 py-2.5 bg-slate-100 dark:bg-slate-800 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-primary hover:text-white transition-all"
                            >
                                Selecionar Arquivo
                            </button>
                        </div>

                        {isPJ && (
                            <div className="p-5 bg-amber-500/5 border border-amber-500/10 rounded-2xl space-y-4">
                                <div className="flex items-center gap-2 text-amber-600 font-black text-[10px] uppercase tracking-widest">
                                    <User size={14} />
                                    Responsável Legal (PF)
                                </div>
                                <Input
                                    label="CPF do Responsável"
                                    {...register("responsible_cpf")}
                                    placeholder="000.000.000-00"
                                    helpText="Vincule este CNPJ a uma Pessoa Física da sua base."
                                />
                            </div>
                        )}
                    </div>
                )}

                {activeSection === "contatos" && (
                    <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-300">
                        <div className="flex items-center justify-between mb-2">
                            <h3 className="text-[10px] font-black uppercase tracking-widest text-slate-400">Contatos do Cliente</h3>
                            <button
                                type="button"
                                onClick={() => append({ name: "", department: "Financeiro", email: "", phone: "" })}
                                className="size-8 rounded-lg bg-emerald-500/10 text-emerald-600 flex items-center justify-center hover:bg-emerald-500 hover:text-white transition-all"
                            >
                                <Plus size={16} />
                            </button>
                        </div>

                        <div className="space-y-3">
                            {fields.map((field, index) => (
                                <div key={field.id} className="p-4 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl space-y-4 relative group">
                                    <button
                                        type="button"
                                        onClick={() => remove(index)}
                                        className="absolute top-4 right-4 text-slate-400 hover:text-rose-500 transition-colors"
                                    >
                                        <Trash2 size={16} />
                                    </button>

                                    <div className="grid grid-cols-2 gap-3">
                                        <Input
                                            label="Nome"
                                            {...register(`contacts.${index}.name` as const)}
                                            placeholder="Ex: Maria"
                                        />
                                        <Input
                                            label="Departamento"
                                            {...register(`contacts.${index}.department` as const)}
                                            placeholder="Ex: Financeiro"
                                        />
                                    </div>
                                    <div className="grid grid-cols-2 gap-3">
                                        <Input
                                            label="E-mail"
                                            {...register(`contacts.${index}.email` as const)}
                                            placeholder="maria@empresa.com"
                                        />
                                        <Input
                                            label="Telefone"
                                            {...register(`contacts.${index}.phone` as const)}
                                            placeholder="(11) 99999-0000"
                                        />
                                    </div>
                                </div>
                            ))}

                            {fields.length === 0 && (
                                <div className="py-12 border-2 border-dashed border-slate-100 dark:border-slate-900 rounded-[2rem] text-center">
                                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em]">Nenhum contato adicional</p>
                                </div>
                            )}
                        </div>
                    </div>
                )}

                <div className="flex flex-col-reverse md:flex-row items-center justify-end gap-3 pt-6 border-t border-slate-100 dark:border-slate-800/50">
                    <button
                        type="button"
                        onClick={onClose}
                        className="w-full md:w-auto px-8 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest text-slate-500 hover:text-slate-900 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-slate-800 transition-all"
                    >
                        Cancelar
                    </button>
                    <button
                        type="submit"
                        disabled={isSubmitting}
                        className="w-full md:flex-1 md:max-w-xs bg-primary text-white px-8 py-3.5 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl shadow-primary/20 hover:scale-[1.02] active:scale-95 transition-all disabled:opacity-50 disabled:scale-100"
                    >
                        {isSubmitting ? "Sincronizando..." : "Salvar na Máquina de Vendas"}
                    </button>
                </div>
            </form>
        </Modal>
    );
}
